node -e "
const sqlite3 = require('better-sqlite3');
const db = sqlite3('/workspace/world.db');

// Check for tau2Retail variant of the product
const products2 = db.prepare(\"SELECT * FROM products WHERE name LIKE '%M310%'\").all();
console.log('All M310 products:', JSON.stringify(products2, null, 2));

// Check compatible products
const compatIds = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
for (const cid of compatIds) {
  const cp = db.prepare('SELECT product_id, name, category FROM products WHERE product_id=?').get(cid);
  console.log('Compatible:', JSON.stringify(cp));
}

// Check tau2Retail variants
const tau2Products = db.prepare(\"SELECT * FROM products WHERE source_skill='tau2Retail' AND name LIKE '%M310%'\").all();
console.log('tau2Retail M310:', JSON.stringify(tau2Products, null, 2));

// Also check rt_variants for the product
const allVariants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id LIKE '%FA0948%'\").all();
console.log('rt_variants:', JSON.stringify(allVariants, null, 2));

// Also look for any tau2Retail product with Wireless Mouse in name
const tau2Mouse = db.prepare(\"SELECT * FROM products WHERE source_skill='tau2Retail' AND name LIKE '%Wireless Mouse%'\").all();
console.log('tau2 Wireless Mouse products:', JSON.stringify(tau2Mouse, null, 2));

db.close();
"
